   {
    "code": "# the two helper modules the code imports, written next to this script, and the trained weights\nimport os, sys\nsys.path.insert(0, os.getcwd())   # import the two files from the folder they are written to\nopen(\"onnx_mini.py\", \"w\").write(\"# onnx_mini.py\\nimport struct, numpy as np\\n\\ndef _varint(n):\\n    out = bytearray()\\n    n &= (1 << 64) - 1\\n    while True:\\n        b = n & 0x7F; n >>= 7\\n        if n: out.append(b | 0x80)\\n        else: out.append(b); return bytes(out)\\n\\ndef _key(field, wire): return _varint((field << 3) | wire)\\ndef f_int(field, v): return _key(field, 0) + _varint(int(v))\\ndef f_bytes(field, b): return _key(field, 2) + _varint(len(b)) + b\\ndef f_str(field, s): return f_bytes(field, s.encode())\\ndef f_float(field, v): return _key(field, 5) + struct.pack('<f', v)\\n\\nDT = {np.float32: 1, np.uint8: 2, np.int8: 3, np.int32: 6, np.int64: 7, np.float16: 10}\\n\\ndef tensor(name, arr):\\n    arr = np.ascontiguousarray(arr)\\n    b = b''.join(f_int(1, d) for d in arr.shape)\\n    b += f_int(2, DT[arr.dtype.type]) + f_str(8, name) + f_bytes(9, arr.tobytes())\\n    return b\\n\\ndef value_info(name, elem, shape):\\n    dims = b''.join(f_bytes(1, f_str(2, d) if isinstance(d, str) else f_int(1, d)) for d in shape)\\n    tt = f_int(1, elem) + f_bytes(2, dims)\\n    return f_str(1, name) + f_bytes(2, f_bytes(1, tt))\\n\\ndef attr(name, v):\\n    b = f_str(1, name)\\n    if isinstance(v, float): return b + f_float(2, v) + f_int(20, 1)\\n    if isinstance(v, int): return b + f_int(3, v) + f_int(20, 2)\\n    if isinstance(v, (list, tuple)): return b + b''.join(f_int(8, x) for x in v) + f_int(20, 7)\\n    raise TypeError(v)\\n\\ndef node(op, inputs, outputs, **attrs):\\n    b = b''.join(f_str(1, i) for i in inputs) + b''.join(f_str(2, o) for o in outputs)\\n    b += f_str(3, outputs[0]) + f_str(4, op)\\n    b += b''.join(f_bytes(5, attr(k, v)) for k, v in attrs.items())\\n    return b\\n\\ndef model(nodes, inits, inputs, outputs, opset=17):\\n    g = b''.join(f_bytes(1, n) for n in nodes) + f_str(2, 'g')\\n    g += b''.join(f_bytes(5, tensor(k, v)) for k, v in inits.items())\\n    g += b''.join(f_bytes(11, value_info(*i)) for i in inputs)\\n    g += b''.join(f_bytes(12, value_info(*o)) for o in outputs)\\n    return f_int(1, 8) + f_bytes(7, g) + f_bytes(8, f_str(1, '') + f_int(2, opset))\")\nopen(\"mlp.py\", \"w\").write('# mlp.py — the data and the forward pass of module 2 (digits, 8 x 8 pixels), and a short training run that writes mlp.npz\\nimport numpy as np\\nfrom sklearn.datasets import load_digits\\n\\ndef data():\\n    d = load_digits()\\n    X = (d.data / 16.0).astype(np.float32)\\n    rng = np.random.default_rng(0)\\n    idx = rng.permutation(len(X))\\n    X, y = X[idx], d.target[idx]\\n    n = int(0.8 * len(X))\\n    return X[:n], X[n:], y[:n], y[n:]\\n\\ndef forward(P, X):\\n    hs = [X]          # the input of every layer, and the output of the last one\\n    h = X\\n    for i, (W, b) in enumerate(P):\\n        h = h @ W + b\\n        if i < len(P) - 1:\\n            h = np.maximum(h, 0)\\n        hs.append(h)\\n    return h, hs\\n\\ndef train(path=\"mlp.npz\", sizes=(64, 64, 32, 10), epochs=60, lr=0.05, seed=0):\\n    Xtr, Xte, ytr, yte = data()\\n    rng = np.random.default_rng(seed)\\n    P = [(rng.normal(0, np.sqrt(2 / a), (a, b)).astype(np.float32), np.zeros(b, np.float32)) for a, b in zip(sizes[:-1], sizes[1:])]\\n    for ep in range(epochs):\\n        for s in range(0, len(Xtr), 32):\\n            x, y = Xtr[s:s + 32], ytr[s:s + 32]\\n            acts = [x]\\n            h = x\\n            for i, (W, b) in enumerate(P):\\n                h = h @ W + b\\n                if i < len(P) - 1:\\n                    h = np.maximum(h, 0)\\n                acts.append(h)\\n            p = np.exp(h - h.max(1, keepdims=True)); p /= p.sum(1, keepdims=True)\\n            g = p; g[np.arange(len(y)), y] -= 1; g /= len(y)\\n            for i in range(len(P) - 1, -1, -1):\\n                W, b = P[i]\\n                gW, gb = acts[i].T @ g, g.sum(0)\\n                if i:\\n                    g = (g @ W.T) * (acts[i] > 0)\\n                P[i] = (W - lr * gW, b - lr * gb)\\n    np.savez(path, *[a for Wb in P for a in Wb])\\n    acc = (forward(P, Xte)[0].argmax(1) == yte).mean()\\n    return acc\\n')\nif not os.path.exists(\"mlp.npz\"):\n    import mlp\n    print(\"trained the module-2 network, test accuracy\", round(float(mlp.train()), 3))\n",
    "say": "שני קבצי עזר שהקוד מייבא — <code class=\"ltr\">onnx_mini.py</code> (הכותב של סעיף 2.3) ו־<code class=\"ltr\">mlp.py</code> (הנתונים והמעבר קדימה של מודול 2, על הספרות של 8 על 8) — נכתבים לתיקייה של הסקריפט, ואם אין עדיין <code class=\"ltr\">mlp.npz</code>, הרשת מאומנת (שנייה בערך) ונשמרת. צריך <code class=\"ltr\">pip install numpy onnxruntime scikit-learn</code>."
   }
