    "code": "# the model this chapter measures: five convolution layers with BatchNorm and an activation, input 640 x 640\n# (built with the small ONNX writer of section 2.3, saved next to this script as onnx_mini.py)\nimport os, sys\nimport numpy as np\nopen(\"onnx_mini.py\", \"w\").write(\"# onnx_mini.py\\nimport struct, numpy as np\\n\\ndef _varint(n):\\n    out = bytearray()\\n    n &= (1 << 64) - 1\\n    while True:\\n        b = n & 0x7F; n >>= 7\\n        if n: out.append(b | 0x80)\\n        else: out.append(b); return bytes(out)\\n\\ndef _key(field, wire): return _varint((field << 3) | wire)\\ndef f_int(field, v): return _key(field, 0) + _varint(int(v))\\ndef f_bytes(field, b): return _key(field, 2) + _varint(len(b)) + b\\ndef f_str(field, s): return f_bytes(field, s.encode())\\ndef f_float(field, v): return _key(field, 5) + struct.pack('<f', v)\\n\\nDT = {np.float32: 1, np.uint8: 2, np.int8: 3, np.int32: 6, np.int64: 7, np.float16: 10}\\n\\ndef tensor(name, arr):\\n    arr = np.ascontiguousarray(arr)\\n    b = b''.join(f_int(1, d) for d in arr.shape)\\n    b += f_int(2, DT[arr.dtype.type]) + f_str(8, name) + f_bytes(9, arr.tobytes())\\n    return b\\n\\ndef value_info(name, elem, shape):\\n    dims = b''.join(f_bytes(1, f_str(2, d) if isinstance(d, str) else f_int(1, d)) for d in shape)\\n    tt = f_int(1, elem) + f_bytes(2, dims)\\n    return f_str(1, name) + f_bytes(2, f_bytes(1, tt))\\n\\ndef attr(name, v):\\n    b = f_str(1, name)\\n    if isinstance(v, float): return b + f_float(2, v) + f_int(20, 1)\\n    if isinstance(v, int): return b + f_int(3, v) + f_int(20, 2)\\n    if isinstance(v, (list, tuple)): return b + b''.join(f_int(8, x) for x in v) + f_int(20, 7)\\n    raise TypeError(v)\\n\\ndef node(op, inputs, outputs, **attrs):\\n    b = b''.join(f_str(1, i) for i in inputs) + b''.join(f_str(2, o) for o in outputs)\\n    b += f_str(3, outputs[0]) + f_str(4, op)\\n    b += b''.join(f_bytes(5, attr(k, v)) for k, v in attrs.items())\\n    return b\\n\\ndef model(nodes, inits, inputs, outputs, opset=17):\\n    g = b''.join(f_bytes(1, n) for n in nodes) + f_str(2, 'g')\\n    g += b''.join(f_bytes(5, tensor(k, v)) for k, v in inits.items())\\n    g += b''.join(f_bytes(11, value_info(*i)) for i in inputs)\\n    g += b''.join(f_bytes(12, value_info(*o)) for o in outputs)\\n    return f_int(1, 8) + f_bytes(7, g) + f_bytes(8, f_str(1, '') + f_int(2, opset))\")\nsys.path.insert(0, os.getcwd())\nfrom onnx_mini import model, node\n\ndef build_backbone(path, ch=(3, 32, 64, 128, 256, 512), seed=0):\n    rng = np.random.default_rng(seed)\n    nodes, inits, x = [], {}, \"images\"\n    for i in range(5):\n        cin, cout = ch[i], ch[i + 1]\n        inits[f\"w{i}\"] = (rng.normal(0, np.sqrt(2 / (9 * cin)), (cout, cin, 3, 3))).astype(np.float32)\n        inits[f\"g{i}\"] = rng.uniform(0.5, 1.5, cout).astype(np.float32)\n        inits[f\"be{i}\"] = rng.normal(0, 0.1, cout).astype(np.float32)\n        inits[f\"m{i}\"] = rng.normal(0, 0.1, cout).astype(np.float32)\n        inits[f\"v{i}\"] = rng.uniform(0.5, 1.5, cout).astype(np.float32)\n        nodes.append(node(\"Conv\", [x, f\"w{i}\"], [f\"c{i}\"], kernel_shape=[3, 3], pads=[1, 1, 1, 1], strides=[2, 2]))\n        nodes.append(node(\"BatchNormalization\", [f\"c{i}\", f\"g{i}\", f\"be{i}\", f\"m{i}\", f\"v{i}\"], [f\"n{i}\"], epsilon=1e-5))\n        nodes.append(node(\"Relu\", [f\"n{i}\"], [f\"r{i}\"]))\n        x = f\"r{i}\"\n    side = 640 // 32\n    open(path, \"wb\").write(model(nodes, inits, [(\"images\", 1, [1, 3, 640, 640])], [(x, 1, [1, ch[-1], side, side])]))\n\nfor name in (\"heavy.onnx\", \"bb.onnx\"):\n    if not os.path.exists(name):\n        build_backbone(name)\n",
    "say": "המודל שהפרק מודד — חמש שכבות קונבולוציה עם נרמול מנה והפעלה, קלט 640 על 640, אותו מודל של פרק 1 — נבנה כאן בכותב הקטן של סעיף 2.3 (שנשמר כ־<code class=\"ltr\">onnx_mini.py</code>), ונשמר כ־<code class=\"ltr\">bb.onnx</code> וכ־<code class=\"ltr\">heavy.onnx</code>. צריך <code class=\"ltr\">pip install numpy onnxruntime</code>."
