    "code": "\n# the timings of the section's table: level x threads, and the largest difference between the outputs\ndef median_ms(s, n=20):\n    for _ in range(3): s.run(None, {'images': x})\n    ts = []\n    for _ in range(n):\n        t0 = time.perf_counter(); s.run(None, {'images': x}); ts.append((time.perf_counter() - t0) * 1000)\n    return float(np.median(ts))\nouts = {}\nfor level in [L.ORT_DISABLE_ALL, L.ORT_ENABLE_ALL]:\n    row = []\n    for th in (1, 2):\n        s = make_session(level, th)\n        row.append('%.1f' % median_ms(s))\n        outs[level] = s.run(None, {'images': x})[0]\n    print(str(level).split('.')[-1], ' 1 thread: %s ms   2 threads: %s ms' % tuple(row))\nprint('largest difference between the two outputs: %.1e' % np.abs(outs[L.ORT_DISABLE_ALL] - outs[L.ORT_ENABLE_ALL]).max())\nfor f in os.listdir('.'):\n    if f.startswith('onnxruntime_profile'): os.remove(f)\n",
