    "code": "import numpy as np\nfrom mlp import data, forward\nfrom quant import fake_sym\nXtr, Xte, ytr, yte = data()\nf = np.load('mlp.npz')\nparams = [(f['arr_%d' % (2 * i)], f['arr_%d' % (2 * i + 1)]) for i in range(len(f.files) // 2)]\nacc = lambda P, q: round(100 * float((forward([(q(W), b) for W, b in P], Xte)[0].argmax(1) == yte).mean()), 1)\nprint(\"2-bit weights, quantized after training:\", acc(params, lambda w: fake_sym(w, 2, axis=0)), \"%\")\n\n# one mini-batch of the training loop of module 2, forward with the quantized weights, up to the gradient g at the output\nlr = 0.02\nx, y = Xtr[:32], ytr[:32]\n_, hs = forward([(fake_sym(W, 2, axis=0), b) for W, b in params], x)\nacts = hs[:-1]\np = np.exp(hs[-1] - hs[-1].max(1, keepdims=True)); p /= p.sum(1, keepdims=True)\ng = p.copy(); g[np.arange(len(y)), y] -= 1; g /= len(y)\n",
