    "code": "import cv2, onnxruntime as ort\n# a synthetic 1920 x 1080 video (moving shapes on a textured background), so the decoder has real work\nif not os.path.exists('drone.mp4'):\n    vw = cv2.VideoWriter('drone.mp4', cv2.VideoWriter_fourcc(*'mp4v'), 30, (1920, 1080))\n    rng = np.random.default_rng(0)\n    bg = cv2.resize(rng.integers(0, 255, (135, 240, 3), dtype=np.uint8), (1920, 1080))\n    for i in range(120):\n        f = bg.copy()\n        cv2.rectangle(f, (100 + 8 * i, 400), (220 + 8 * i, 470), (40, 40, 200), -1)\n        cv2.circle(f, (1500 - 6 * i, 700), 40, (200, 200, 40), -1)\n        vw.write(f)\n    vw.release()\n\ndef letterbox(img, size=640):\n    h, w = img.shape[:2]; r = size / max(h, w)\n    out = np.full((size, size, 3), 114, np.uint8)\n    nh, nw = int(h * r), int(w * r)\n    out[(size - nh) // 2:(size - nh) // 2 + nh, (size - nw) // 2:(size - nw) // 2 + nw] = cv2.resize(img, (nw, nh))\n    return out\n\nso = ort.SessionOptions(); so.intra_op_num_threads = 2\nsess = ort.InferenceSession('heavy.onnx', so, providers=['CPUExecutionProvider'])\n",
