    "code": "open(\"quant.py\", \"w\").write('# quant.py\\nimport numpy as np\\n\\ndef quant_sym(x, bits=8, axis=None):\\n    qmax = 2 ** (bits - 1) - 1\\n    m = np.abs(x).max() if axis is None else np.abs(x).max(axis=axis, keepdims=True)\\n    s = np.maximum(m, 1e-12) / qmax\\n    q = np.clip(np.round(x / s), -qmax, qmax).astype(np.int8)\\n    return q, s\\n\\ndef fake_sym(x, bits=8, axis=None):\\n    q, s = quant_sym(x, bits, axis)\\n    return q.astype(np.float32) * s\\n\\ndef qparams_asym(lo, hi, bits=8):\\n    qmax = 2 ** bits - 1\\n    lo, hi = min(lo, 0.0), max(hi, 0.0)\\n    s = max(hi - lo, 1e-12) / qmax\\n    z = int(round(-lo / s))\\n    return s, z\\n\\ndef fake_asym(x, s, z, bits=8):\\n    q = np.clip(np.round(x / s) + z, 0, 2 ** bits - 1)\\n    return ((q - z) * s).astype(np.float32)')\n",
