    "code": "# export_mlp.py\nimport numpy as np, onnxruntime as ort\nfrom onnx_mini import model, node\nfrom mlp import data, forward\n\nf = np.load('mlp.npz')\nP = [(f['arr_%d' % (2 * i)], f['arr_%d' % (2 * i + 1)]) for i in range(3)]\n\ndef export(path, batch='N'):\n    nodes, inits, x = [], {}, 'pixels'\n    for i, (W, b) in enumerate(P):\n        inits[f'W{i}'], inits[f'b{i}'] = W, b\n        nodes.append(node('Gemm', [x, f'W{i}', f'b{i}'], [f'h{i}']))\n        x = f'h{i}'\n        if i < len(P) - 1:\n            nodes.append(node('Relu', [x], [f'r{i}']))\n            x = f'r{i}'\n    m = model(nodes, inits, [('pixels', 1, [batch, 64])], [(x, 1, [batch, 10])])\n    open(path, 'wb').write(m)\n\nexport('mlp.onnx')\n",
